"""Transformation `lab_control_check`: generated by package-factory from approved specs. Do not edit here.

Requirement (approved):
  The package contains one or more delivery folders at the top level. Each delivery folder must contain exactly one
  control file named CONTROL_<n>.txt, where <n> is the number of other files in that same folder (sub-folders
  included); refuse the whole package if a folder has no control file, more than one, or a count that does not
  match. After the check, remove the control files, move every remaining file to data/<delivery folder>/<file
  name> (dropping any sub-folders), compute md5 and sha256 for every file, and write manifest.csv at the package
  root with path, size, md5 and sha256.
Plan approved by @claude-demo at 2026-10-16T12:43:58+00:00
Code approved by @claude-demo at 2026-10-16T12:44:18+00:00

Steps:
  1. check_control_files [custom] Verify each delivery folder has one control file with a matching file count
  2. drop_control_files [select] Remove the control files
  3. move_to_data [move] Move files to data/<delivery folder>/<file name>, dropping sub-folders
  4. compute_checksums [checksum] Compute md5 and sha256 for every file
  5. write_manifest [manifest] Write manifest.csv with path, size, md5, sha256
Custom functions: (pkg, params, ctx) -> None
"""
from __future__ import annotations

KIND = 'transformation'

STEPS = [{'id': 'check_control_files',
  'op': 'custom',
  'title': 'Verify each delivery folder has one control file with a matching file count',
  'params': {'function': 'check_control_files'}},
 {'id': 'drop_control_files',
  'op': 'select',
  'title': 'Remove the control files',
  'params': {'exclude': ['*/CONTROL_*.txt']}},
 {'id': 'move_to_data',
  'op': 'move',
  'title': 'Move files to data/<delivery folder>/<file name>, dropping sub-folders',
  'params': {'match': '(?P<delivery>[^/]+)/(?:.*/)?(?P<fname>[^/]+)', 'to': 'data/{delivery}/{fname}'}},
 {'id': 'compute_checksums',
  'op': 'checksum',
  'title': 'Compute md5 and sha256 for every file',
  'params': {'algorithms': ['md5', 'sha256']}},
 {'id': 'write_manifest',
  'op': 'manifest',
  'title': 'Write manifest.csv with path, size, md5, sha256',
  'params': {'path': 'manifest.csv', 'format': 'csv', 'fields': ['path', 'size', 'md5', 'sha256']}}]


def check_control_files(pkg, params, ctx):
    import re
    files = pkg.files()
    if not files:
        pkg.fail('empty package')
        return
    pattern = re.compile(r'CONTROL_(\d+)\.txt')
    groups = {}
    for path in files:
        parts = path.split('/')
        if len(parts) < 2:
            pkg.fail('file outside a delivery folder')
            return
        groups.setdefault(parts[0], []).append(parts[1:])
    for folder in sorted(groups):
        rest_list = groups[folder]
        controls = []
        for rest in rest_list:
            m = pattern.fullmatch(rest[-1])
            if m:
                controls.append(m)
        if len(controls) != 1:
            pkg.fail('delivery folder %s must have exactly one control file, found %d' % (folder, len(controls)))
            return
        n = int(controls[0].group(1))
        others = len(rest_list) - 1
        if n != others:
            pkg.fail('delivery folder %s control count mismatch: expected %d, actual %d' % (folder, n, others))
            return


CUSTOM = {"check_control_files": check_control_files}
